//! regexp2 Unicode 17 predicates, generated by `go run tools/tsgolint/gen-regexp-unicode.go`.

fn has_flag(ch: char, flag: u8) -> bool {
    let code = ch as u32;
    let index = RANGES.partition_point(|&(_, end, _)| end < code);
    RANGES.get(index).is_some_and(|&(start, _, flags)| start <= code && flags & flag != 0)
}

pub(super) fn is_word_char(ch: char) -> bool {
    has_flag(ch, 1)
}
pub(super) fn is_identifier_start(ch: char) -> bool {
    has_flag(ch, 2)
}
pub(super) fn is_identifier_part(ch: char) -> bool {
    has_flag(ch, 4)
}

